head.script:
scwin.onpageload = async function () {
    // 메인 페이지 초기화
    await scwin.loadUserInfo();

    // 기본적으로 대시보드 로드 (사용자 정보 로드 후 진행)
    await scwin.loadMainContent("dashboard");
};

// 메인 콘텐츠 동적 로드 함수
scwin.loadMainContent = function (menuType, projectData) {
    try {
        let srcPath = "";

        console.log("=== 메인 콘텐츠 로드 시작 ===");
        console.log("요청된 메뉴 타입:", menuType);
        console.log("프로젝트 데이터:", projectData);

        if (menuType && menuType.startsWith("project_")) {
            // 동적 프로젝트 메뉴인 경우
            if (projectData) {
                // 특정 프로젝트 상세 페이지로 이동
                srcPath = "/InsWebApp/ui/project/projectMainPage.xml";
                console.log("프로젝트 상세 페이지로 이동:", projectData.projectName);
            } else {
                // 기본 프로젝트 페이지
                srcPath = "/InsWebApp/ui/project/ProjectList.xml";
            }
        } else {
            // 기존 정적 메뉴들
            switch (menuType) {
                case "dashboard":
                    srcPath = "/InsWebApp/ui/mainContent.xml";
                    break;
                case "project1":
                    srcPath = "/InsWebApp/ui/project1Content.xml";
                    break;
                case "project2":
                    srcPath = "/InsWebApp/ui/project2Content.xml";
                    break;
                default:
                    srcPath = "/InsWebApp/ui/mainContent.xml";
                    console.log("기본 대시보드로 설정:", menuType);
                    break;
            }
        }

        console.log("결정된 소스 경로:", srcPath);

        // wframe 존재 확인
        if (wfr_mainContent) {
            console.log("wfr_mainContent 찾음:", wfr_mainContent);
            console.log("현재 wframe src:", wfr_mainContent.getSrc());

            // 프레임 소스 변경
            wfr_mainContent.setSrc(srcPath);

            // 변경 후 확인
            setTimeout(function () {
                console.log("변경 후 wframe src:", wfr_mainContent.getSrc());
                console.log("프레임 소스 변경 성공:", srcPath);

                // 프로젝트 데이터가 있으면 메인 콘텐츠에 전달
                if (projectData) {
                    setTimeout(() => {
                        try {
                            const mainContentWindow = wfr_mainContent.getWindow();
                            if (mainContentWindow && mainContentWindow.scwin && mainContentWindow.scwin.setProjectData) {
                                mainContentWindow.scwin.setProjectData(projectData);
                                console.log("메인 콘텐츠에 프로젝트 데이터 전달 성공");
                            }
                        } catch(e) {
                            console.log("프로젝트 데이터 전달 오류:", e);
                        }
                    }, 800);
                }
            }, 100);

        } else {
            console.error("오류: wfr_mainContent를 찾을 수 없습니다.");
            return false;
        }

        // 프레임이 로드된 후 사용자 정보 전달
        setTimeout(() => {
            scwin.updateMainContentUserInfo();
        }, 500);

        console.log("=== 메인 콘텐츠 로드 완료 ===");
        return true;

    } catch (e) {
        console.error("메인 콘텐츠 로드 오류:", e);
        console.error("Error stack:", e.stack);
        return false;
    }
};

// 메인 콘텐츠에 사용자 정보 업데이트
scwin.updateMainContentUserInfo = function () {
    try {
        if (wfr_mainContent && wfr_mainContent.getWindow) {
            const mainContentWindow = wfr_mainContent.getWindow();
            if (mainContentWindow && mainContentWindow.dm_userInfo) {
                const userName = dm_userInfo.get("userName");
                const userId = dm_userInfo.get("userId");

                console.log("메인페이지에서 가져온 사용자 정보:");
                console.log("- userName:", userName);
                console.log("- userId:", userId);

                // 사용자 정보 업데이트
                mainContentWindow.dm_userInfo.set("userName", userName);
                mainContentWindow.dm_userInfo.set("userId", userId);

                console.log("하위 콘텐츠로 전달한 사용자 정보:");
                console.log("- userName:", userName);
                console.log("- userId:", userId);

                // 프로젝트 조회 파라미터도 업데이트
                if (mainContentWindow.dmp_projectVo) {
                    mainContentWindow.dmp_projectVo.set("userId", userId);
                }

                // 환영 메시지 업데이트 (대시보드인 경우)
                if (mainContentWindow.scwin && mainContentWindow.scwin.updateWelcomeMessage) {
                    mainContentWindow.scwin.updateWelcomeMessage();
                }

                // 사용자 정보 설정 완료 후 프로젝트 목록 조회
                if (mainContentWindow.scwin && mainContentWindow.scwin.loadProjectList) {
                    mainContentWindow.scwin.loadProjectList();
                }

                console.log("메인 콘텐츠에 사용자 정보 전달 성공:", userName);
            }
        }
    } catch (e) {
        console.log("메인 콘텐츠 사용자 정보 업데이트 오류:", e);
    }
};

// 사이드메뉴에서 호출할 메뉴 변경 함수
scwin.changeMenu = function (menuType, projectData) {
    console.log("=== 메뉴 변경 요청 ===", menuType, projectData);

    // 메인 콘텐츠 로드
    scwin.loadMainContent(menuType, projectData);

    // 사이드메뉴에 선택된 메뉴 알림
    try {
        if (wfr_sideMenu && wfr_sideMenu.getWindow) {
            const sideMenuWindow = wfr_sideMenu.getWindow();
            if (sideMenuWindow && sideMenuWindow.scwin && sideMenuWindow.scwin.updateSelectedMenu) {
                sideMenuWindow.scwin.updateSelectedMenu(menuType);
                console.log("사이드메뉴 선택 상태 업데이트 성공:", menuType);
            } else {
                console.log("사이드메뉴 updateSelectedMenu 함수를 찾을 수 없습니다.");
            }
        } else {
            console.log("사이드메뉴 wframe을 찾을 수 없습니다.");
        }
    } catch (e) {
        console.log("사이드메뉴 업데이트 오류:", e);
    }
};

// 사용자 정보 로드 - 세션에서 사용자 정보 가져오기
scwin.loadUserInfo = function () {
    try {
        console.log("세션에서 사용자 정보를 가져오는 중...");

        // 서버에 세션 사용자 정보 요청
        $p.executeSubmission("sbm_getUserInfo");

    } catch (e) {
        // console.log("사용자 정보 로드 오류:", e);
        // // 오류 시 기본값 사용
        // dm_userInfo.set("userId", "user01");
        // dm_userInfo.set("userName", "식스센스");
        // scwin.updateUserInfoInComponents();
    }
};

// 헤더 컴포넌트에 사용자 정보 전달
scwin.updateUserInfoInComponents = async function () {
    try {
        // 헤더 컴포넌트가 완전히 로드될 때까지 대기
        await scwin.waitForHeaderLoad();

        // 헤더 컴포넌트에 사용자 정보 전달
        try {
            if (wfr_header && wfr_header.getWindow) {
                const headerWindow = wfr_header.getWindow();
                if (headerWindow && headerWindow.dm_header) {
                    const userName = dm_userInfo.get("userName");
                    headerWindow.dm_header.set("userName", userName);
                    console.log("헤더에 사용자 정보 전달 성공:", userName);

                    // 헤더의 output_userName 컴포넌트 직접 업데이트
                    if (headerWindow.output_userName) {
                        headerWindow.output_userName.setValue(userName);
                        console.log("헤더 사용자명 컴포넌트 직접 업데이트 완료:", userName);
                    }
                } else {
                    console.log("헤더 dm_header를 찾을 수 없습니다.");
                }
            } else {
                console.log("헤더 컴포넌트를 찾을 수 없습니다.");
            }
        } catch (e) {
            console.log("헤더 업데이트 오류:", e);
        }

        // 메인 콘텐츠에 사용자 정보 전달
        try {
            if (wfr_mainContent && wfr_mainContent.getWindow) {
                const mainContentWindow = wfr_mainContent.getWindow();
                if (mainContentWindow && mainContentWindow.dm_userInfo) {
                    const userName = dm_userInfo.get("userName");
                    mainContentWindow.dm_userInfo.set("userName", userName);

                    // 메인 콘텐츠의 환영 메시지 업데이트
                    if (mainContentWindow.scwin && mainContentWindow.scwin.updateWelcomeMessage) {
                        mainContentWindow.scwin.updateWelcomeMessage();
                        console.log("메인 콘텐츠에 사용자 정보 전달 성공:", userName);
                    }
                } else {
                    console.log("메인 콘텐츠 dm_userInfo를 찾을 수 없습니다.");
                }
            } else {
                console.log("메인 콘텐츠 컴포넌트를 찾을 수 없습니다.");
            }
        } catch (e) {
            console.log("메인 콘텐츠 업데이트 오류:", e);
        }

        // 사이드메뉴에 사용자 정보 전달
        await scwin.waitForSideMenuLoad();
        try {
            if (wfr_sideMenu && wfr_sideMenu.getWindow) {
                const sideMenuWindow = wfr_sideMenu.getWindow();
                if (sideMenuWindow && sideMenuWindow.scwin && sideMenuWindow.scwin.setUserInfo) {
                    const userId = dm_userInfo.get("userId");
                    sideMenuWindow.scwin.setUserInfo(userId);
                    console.log("사이드메뉴에 사용자 정보 전달 성공:", userId);
                } else {
                    console.log("사이드메뉴 setUserInfo 함수를 찾을 수 없습니다.");
                }
            } else {
                console.log("사이드메뉴 컴포넌트를 찾을 수 없습니다.");
            }
        } catch (e) {
            console.log("사이드메뉴 업데이트 오류:", e);
        }

    } catch (e) {
        console.log("컴포넌트 업데이트 오류:", e);
    }
};

// 헤더 로드 대기 함수
scwin.waitForHeaderLoad = function () {
    return new Promise((resolve) => {
        const checkHeader = () => {
            if (wfr_header && wfr_header.getWindow && wfr_header.getWindow().dm_header) {
                resolve();
            } else {
                setTimeout(checkHeader, 100);
            }
        };
        checkHeader();
    });
};

// 사이드메뉴 로드 대기 함수
scwin.waitForSideMenuLoad = function () {
    return new Promise((resolve) => {
        const checkSideMenu = () => {
            if (wfr_sideMenu && wfr_sideMenu.getWindow && wfr_sideMenu.getWindow().scwin) {
                resolve();
            } else {
                setTimeout(checkSideMenu, 100);
            }
        };
        checkSideMenu();
    });
};

// 사용자 정보 서버 요청 성공
scwin.sbm_getUserInfo_submitdone = function (e) {
    try {
        var responseData = e.responseJSON;
        console.log("서버에서 받은 사용자 정보:", responseData);

        if (responseData && responseData.userVo) {
            var userData = responseData.userVo;
            console.log(userData);
            if (userData.userName && userData.userId) {
                dm_userInfo.set("userName", userData.userName);
                dm_userInfo.set("userId", userData.userId);
                console.log("세션에서 가져온 사용자 정보 설정 성공:", userData.userName);
                scwin.updateUserInfoInComponents();
            } else {
                // 사용자 정보가 없는 경우 기본값 사용
                console.log("서버에서 받은 사용자 정보가 불완전합니다. 기본값 사용.");
                dm_userInfo.set("userId", "user01");
                dm_userInfo.set("userName", "식스센스");
                scwin.updateUserInfoInComponents();
            }
        } else {
            // 응답 데이터가 없는 경우 기본값 사용
            console.log("서버 응답 데이터가 없습니다. 기본값 사용.");
            dm_userInfo.set("userId", "user01");
            dm_userInfo.set("userName", "식스센스");
            scwin.updateUserInfoInComponents();
        }
    } catch (err) {
        console.log("사용자 정보 처리 오류:", err);
        // 오류 시 기본값 사용
        dm_userInfo.set("userId", "user01");
        dm_userInfo.set("userName", "식스센스");
        scwin.updateUserInfoInComponents();
    }
};

// 사용자 정보 서버 요청 실패
scwin.sbm_getUserInfo_submiterror = function (e) {
    console.log("사용자 정보 요청 실패:", e);
    // 실패 시 기본값 사용
    dm_userInfo.set("userName", "식스센스");
    scwin.updateUserInfoInComponents();
};

// 전역 변수로 모달 상태 관리 개선
scwin.modalManager = {
    isModalOpen: false,
    modalId: "projectAddModal",
    modalInstance: null
};

// 프로젝트 추가 모달 열기
scwin.openProjectAddModal = function () {
    try {
        // 기존 모달이 있다면 완전히 제거
        scwin.cleanupModal();

        console.log("=== 프로젝트 추가 모달 열기 ===");

        // 모달 생성
        scwin.createProjectAddModal();

    } catch (e) {
        console.error("프로젝트 추가 모달 열기 오류:", e);
        scwin.modalManager.isModalOpen = false;
    }
};

// 기존 모달 완전히 정리하는 함수
scwin.cleanupModal = function() {
    try {
        // WebSquare 팝업이 열려있는지 확인하고 닫기
        if ($p.getPopupWindow(scwin.modalManager.modalId)) {
            console.log("기존 모달 발견, 닫는 중...");
            $p.closePopup(scwin.modalManager.modalId);
        }

        // 모달 상태 초기화
        scwin.modalManager.isModalOpen = false;
        scwin.modalManager.modalInstance = null;

        // DOM에서 혹시 남아있을 수 있는 모달 엘리먼트들 제거
        var existingModals = document.querySelectorAll('[id*="' + scwin.modalManager.modalId + '"]');
        existingModals.forEach(function(modal) {
            if (modal && modal.parentNode) {
                modal.parentNode.removeChild(modal);
                console.log("DOM에서 모달 엘리먼트 제거:", modal.id);
            }
        });

    } catch (e) {
        console.error("모달 정리 중 오류:", e);
    }
};

// 프로젝트 추가 모달 생성 (강화된 버전)
scwin.createProjectAddModal = function () {
    // mainPage의 userInfo에서 사용자 정보 가져오기
    let userName = dm_userInfo.get("userName") || "식스센스";
    let userId = dm_userInfo.get("userId") || "user01";
    // 팝업 화면에 데이터를 전달
    let jsnPopupData = {
        "type": "json",
        "name": "project_param",
        "data": {
            "userName": userName,
            "userId": userId
        }
    };

    // 고유한 모달 ID 생성 (시간 기반)
    let uniqueModalId = scwin.modalManager.modalId + "_" + new Date().getTime();

    // 팝업 생성 옵션 지정
    let options = {
        id: uniqueModalId,  // 고유한 ID 사용
        type: "wframePopup",
        width: "500px",
        height: "750px",
        top: "100px",
        left: "" + ((window.screen.width / 2) - 250) + "px",
        popupName: "프로젝트 추가",
        modal: true,
        closeAction: "scwin.popup_closeAction",
        dataObject: jsnPopupData,
        useMaximize: false,
    };

    console.log("모달에 전달할 사용자 정보:", jsnPopupData);
    console.log("사용할 모달 ID:", uniqueModalId);

    // 팝업 생성
    try {
        scwin.modalManager.modalInstance = $p.openPopup("/InsWebApp/ui/cmmn/projectAddModal.xml", options);
        scwin.modalManager.isModalOpen = true;
        scwin.modalManager.modalId = uniqueModalId; // 새로운 ID로 업데이트

        console.log("WebSquare 모달 생성 완료 - 팀장:", userName);
        console.log("모달 인스턴스:", scwin.modalManager.modalInstance);

    } catch (e) {
        console.error("모달 생성 중 오류:", e);
        scwin.modalManager.isModalOpen = false;
    }
};

// 사이드메뉴 새로고침
scwin.refreshSideMenu = function () {
    try {
        if (wfr_sideMenu && wfr_sideMenu.getWindow && wfr_sideMenu.getWindow().scwin) {
            const sideMenuWindow = wfr_sideMenu.getWindow();
            if (sideMenuWindow.scwin.refreshProjectList) {
                sideMenuWindow.scwin.refreshProjectList();
                console.log("사이드메뉴 프로젝트 목록 새로고침 완료");
            } else {
                // fallback: 전체 사이드메뉴 새로고침
                wfr_sideMenu.setSrc(wfr_sideMenu.getSrc());
                console.log("사이드메뉴 전체 새로고침 완료");
            }
        }
    } catch (e) {
        console.log("사이드메뉴 새로고침 오류:", e);
    }
};

// 메인 콘텐츠 새로고침
scwin.refreshMainContent = function () {
    try {
        if (wfr_mainContent && wfr_mainContent.getWindow && wfr_mainContent.getWindow().scwin) {
            const mainContentWindow = wfr_mainContent.getWindow();
            if (mainContentWindow.scwin.loadProjectList) {
                // 메인 콘텐츠의 프로젝트 목록 다시 로드
                mainContentWindow.scwin.loadProjectList();
                console.log("메인 콘텐츠 프로젝트 목록 새로고침 완료");
            } else {
                console.log("메인 콘텐츠의 loadProjectList 함수를 찾을 수 없습니다.");
            }
        }
    } catch (e) {
        console.log("메인 콘텐츠 새로고침 오류:", e);
    }
};

// 팝업 닫기 액션 (최종 버전)
scwin.popup_closeAction = function(argRuntimeID, argJsnInfo) {
    console.log("팝업 닫기 액션 호출:", argRuntimeID);
    console.log("팝업 정보:", argJsnInfo);
    try {
        // 팝업 객체 접근
        let popObj = $p.getPopupWindow(argRuntimeID);

        // 모달 상태 초기화
        scwin.modalManager.isModalOpen = false;
        scwin.modalManager.modalInstance = null;

        // 프로젝트가 추가되었다면 사이드메뉴 새로고침
        if (argJsnInfo && argJsnInfo.projectAdded) {
            console.log("프로젝트가 추가되어 사이드메뉴를 새로고침합니다.");
            setTimeout(() => {
                scwin.refreshSideMenu();
            }, 500);
        }

        console.log("팝업 닫기 액션 완료");

        return true; // 팝업 닫기 허용

    } catch (e) {
        console.error("팝업 닫기 액션 오류:", e);

        // 오류가 있어도 레이아웃과 모달 상태는 초기화
        scwin.modalManager.isModalOpen = false;
        scwin.modalManager.modalInstance = null;

        return true; // 팝업 닫기 허용
    }
};
